{
  "width": 900,
  "height": 110,
  "controls": [
    {
      "type": "select",
      "label": "Start with",
      "bind": "life_start",
      "default": "rpent",
      "options": [
        {
          "label": "R-pentomino alone",
          "value": "rpent"
        },
        {
          "label": "R-pentomino + corner soup",
          "value": "rpent_soup"
        },
        {
          "label": "Glider gun",
          "value": "gun"
        },
        {
          "label": "Random soup",
          "value": "soup"
        }
      ],
      "x": 0,
      "y": 0,
      "width": 420,
      "height": 76
    },
    {
      "type": "slider",
      "label": "Generations",
      "bind": "life_gens",
      "default": 300,
      "min": 50,
      "max": 400,
      "step": 10,
      "x": 450,
      "y": 0,
      "width": 420,
      "height": 76
    }
  ]
}

#include <stdio.h>
#include <string.h>
#include <nb.h>

/* world is 40x28 with a dead border row/column all round */
int cur[30][42];
int nxt[30][42];
int W = 40;
int H = 28;

/* Gosper glider gun, as (x, y) pairs */
int gun[36][2] = {
    {24,0},{22,1},{24,1},{12,2},{13,2},{20,2},{21,2},{34,2},{35,2},
    {11,3},{15,3},{20,3},{21,3},{34,3},{35,3},{0,4},{1,4},{10,4},
    {16,4},{20,4},{21,4},{0,5},{1,5},{10,5},{14,5},{16,5},{17,5},
    {22,5},{24,5},{10,6},{16,6},{24,6},{11,7},{15,7},{12,8},{13,8}
};

int seed = 4242;
int next_random() {
    seed = (seed * 75 + 74) % 65537;
    return seed;
}

int population() {
    int p = 0;
    for (int y = 1; y <= H; y++)
        for (int x = 1; x <= W; x++) p += cur[y][x];
    return p;
}

void emit_frame() {
    /* pack 4 cells per hex digit, row-major: 40*28/4 = 280 digits */
    printf("\"");
    for (int y = 1; y <= H; y++) {
        for (int x = 1; x <= W; x += 4) {
            int nib = cur[y][x] * 8 + cur[y][x + 1] * 4 + cur[y][x + 2] * 2 + cur[y][x + 3];
            printf("%x", nib);
        }
    }
    printf("\"");
}

int main() {
    char start[32];
    if (nb_get_string("life_start", start, sizeof start) < 0) strcpy(start, "rpent");
    int gens = (int)nb_get_int("life_gens", 300);
    if (gens < 1) gens = 1;
    if (gens > 400) gens = 400;

    for (int y = 0; y < 30; y++)
        for (int x = 0; x < 42; x++) { cur[y][x] = 0; nxt[y][x] = 0; }

    if (strcmp(start, "gun") == 0) {
        for (int i = 0; i < 36; i++) cur[gun[i][1] + 2][gun[i][0] + 2] = 1;
    } else if (strcmp(start, "soup") == 0) {
        for (int y = 1; y <= H; y++)
            for (int x = 1; x <= W; x++)
                if (next_random() % 100 < 35) cur[y][x] = 1;
    } else {
        /* r-pentomino near the centre - the famous long-lived starter */
        cur[13][20] = 1; cur[13][21] = 1;
        cur[14][19] = 1; cur[14][20] = 1;
        cur[15][20] = 1;
        if (strcmp(start, "rpent_soup") == 0) {
            for (int y = 1; y <= H; y++) {
                for (int x = 1; x <= W; x++) {
                    int r = next_random();
                    int corner = (x < 12 || x > W - 11) && (y < 9 || y > H - 8);
                    if (corner && r % 100 < 22) cur[y][x] = 1;
                }
            }
        }
    }

    int first = population();
    int most = first, most_at = 0;
    printf("__NB_SET__ {\"key\":\"life\",\"value\":{\"w\":%d,\"h\":%d,\"start\":\"%s\",\"frames\":[", W, H, start);
    emit_frame();

    for (int g = 1; g <= gens; g++) {
        for (int y = 1; y <= H; y++) {
            for (int x = 1; x <= W; x++) {
                int n = cur[y-1][x-1] + cur[y-1][x] + cur[y-1][x+1]
                      + cur[y][x-1]                 + cur[y][x+1]
                      + cur[y+1][x-1] + cur[y+1][x] + cur[y+1][x+1];
                if (cur[y][x] == 1) nxt[y][x] = (n == 2 || n == 3) ? 1 : 0;
                else                nxt[y][x] = (n == 3) ? 1 : 0;
            }
        }
        for (int y = 1; y <= H; y++)
            for (int x = 1; x <= W; x++) cur[y][x] = nxt[y][x];
        int p = population();
        if (p > most) { most = p; most_at = g; }
        printf(",");
        emit_frame();
    }
    printf("]}}\n");
    printf("start: %s, %d live cells\n", start, first);
    printf("largest population: %d at generation %d\n", most, most_at);
    printf("after %d generations: %d live cells\n", gens, population());
    return 0;
}

// Decode the recording and find where the world starts repeating itself.
const life = nb.get('life');
if (!life) return 'Run the C cell first.';

const decode = hex => {
  const cells = new Uint8Array(life.w * life.h);
  for (let i = 0; i < cells.length; i++) {
    cells[i] = (parseInt(hex[i >> 2], 16) >> (3 - (i & 3))) & 1;
  }
  return cells;
};

const rows = [];
const seen = new Map();          // frame text -> first generation it appeared
let cycleStart = null, period = null;
let prev = null;
life.frames.forEach((hex, g) => {
  const cells = decode(hex);
  let pop = 0, born = 0, died = 0;
  for (let i = 0; i < cells.length; i++) {
    pop += cells[i];
    if (prev && cells[i] && !prev[i]) born++;
    if (prev && !cells[i] && prev[i]) died++;
  }
  rows.push({ generation: g, cells: pop, series: 'population' });
  if (g > 0) {
    rows.push({ generation: g, cells: born, series: 'births' });
    rows.push({ generation: g, cells: died, series: 'deaths' });
  }
  if (cycleStart === null && seen.has(hex)) {
    cycleStart = seen.get(hex);
    period = g - cycleStart;
  }
  if (!seen.has(hex)) seen.set(hex, g);
  prev = cells;
});

const last = rows.filter(r => r.series === 'population').at(-1);
console.log('start pattern:', life.start, '-', life.frames.length - 1, 'generations recorded');
console.log('final population:', last.cells);
if (cycleStart === null) {
  console.log('no repeat yet - the world is still new after', life.frames.length - 1, 'generations');
} else {
  console.log('the board first repeats at generation', cycleStart + period,
    '- it is the board of generation', cycleStart, '(period', period + ')');
}

const layers = [{
  mark: { type: 'line', strokeWidth: 1.5 },
  encoding: {
    y: { field: 'cells', type: 'quantitative', title: 'cells' },
    color: { field: 'series', type: 'nominal', title: null,
      scale: { domain: ['population', 'births', 'deaths'], range: ['#38bdf8', '#4ade80', '#f472b6'] } },
  },
}];
if (cycleStart !== null) {
  layers.push({
    data: { values: [{ generation: cycleStart }] },
    mark: { type: 'rule', strokeDash: [5, 4], color: '#facc15' },
  });
}
return {
  $schema: 'https://vega.github.io/schema/vega-lite/v5.json',
  width: 'container',
  height: 280,
  title: cycleStart === null ? 'No repeat within the run'
    : 'Repeats from generation ' + cycleStart + ' (period ' + period + ')',
  data: { values: rows },
  encoding: { x: { field: 'generation', type: 'quantitative' } },
  layer: layers,
};
